/* "Your trial, adjusted": covariate adjustment in a randomized device trial.
 * All repeated-trial numbers come from science/rct-adjustment.json, generated by
 * CausalRCT.precompute(); the single "your trial" example is regenerated live from the same seed. */
(function () {
  const { S, store, control, tools, guided, table, fmt } = CausalLab,
    { el, html, Plot, player } = CausalAnim,
    R = CausalRCT,
    G = R.GRID,
    M = 60, // metres per SD of the outcome (change in 6-minute walk distance)
    root = document.querySelector("[data-lab]"),
    byId = (id) => document.getElementById(id),
    nearest = (grid, v) =>
      grid.reduce((b, g) => (Math.abs(g - v) < Math.abs(b - v) ? g : b), grid[0]),
    state = store(
      "rct-adjustment",
      { step: 0, r2: 0.5, curve: 0.5, model: "linear", gap: 2.5, or: 3, pi: 0.25, het: 1.5, nHist: 1000 },
      {
        step: [0, 5], r2: [0, 0.8], curve: [0, 1], model: ["linear", "quadratic", "sign"],
        gap: [0, 3], or: [1.5, 5], pi: [0.25, 0.75], het: [0, 2], nHist: [20, 5000],
      },
    ),
    // Fixed decimals so columns line up; tiny negatives print as 0.
    fx = (x, d = 1) =>
      Number.isFinite(x) ? (Math.abs(x) < 0.5 * 10 ** -d ? 0 : x).toFixed(d) : "undefined",
    m = (x, d = 1) => fx(x * M, d),
    pct = (x, d = 1) => fx(x * 100, d) + "%",
    swatch = (color, kind = "line", dash = "") =>
      kind === "bar"
        ? `<svg class="swatch" width="28" height="10" aria-hidden="true"><rect x="1" y="1" width="26" height="8" rx="2" fill="${color}" fill-opacity=".55"/></svg>`
        : kind === "dot"
          ? `<svg class="swatch" width="28" height="10" aria-hidden="true"><circle cx="14" cy="5" r="4" fill="${color}"/></svg>`
          : `<svg class="swatch" width="28" height="10" aria-hidden="true"><line x1="1" y1="5" x2="27" y2="5" stroke="${color}" stroke-width="2.5" ${dash ? `stroke-dasharray="${dash}"` : ""}/></svg>`,
    legend = (items) =>
      `<p class="legend legend-swatches">${items.map(([c, k, t, d]) => `<span>${swatch(c, k, d)}${t}</span>`).join("")}</p>`,
    // One viewBox unit is about one CSS pixel, so figure text stays legible on phones.
    fitW = (svg) => Math.round(Math.max(330, Math.min(640, svg.parentElement?.clientWidth || 640))),
    mkPlot = (svg, o) => new Plot(svg, { ...o, width: fitW(svg) }),
    narrow = (svg) => fitW(svg) < 500,
    effectTicks = (svg) => (narrow(svg) ? [-20, 0, 20, 40] : undefined),
    readout = (id, pairs) =>
      byId(id).replaceChildren(
        ...pairs.flatMap(([k, v]) => [html("span", { class: "k" }, k), html("span", {}, String(v))]),
      );

  root.innerHTML = `
<section class="lab-step" data-title="One trial is noisy"><h2 tabindex="-1">A fair trial can still be a noisy trial</h2>
<p>A heart-failure device is tested in a randomized trial of 200 patients, exactly 100 per arm. The primary outcome is the change in 6-minute walk distance at 12 weeks. Patients vary a lot: the outcome's standard deviation is ${M} metres. The device truly adds 15 metres on average.</p>
<p>The simplest analysis compares the two arm means. Randomization makes that difference unbiased: over many repetitions of the same trial, it averages exactly the true effect. But you only get one trial.</p>
<div class="predict" data-options="Centered on the true 15 m|Pulled toward zero|Centered wherever the first trial landed" data-answer="0" data-hint="Randomization makes the difference in means unbiased: its histogram centers on the truth. The spread is the problem, not the center.">Imagine running this exact trial 400 times with new patients. Where will the pile of difference-in-means estimates be centered?</div>
<div class="figure"><div class="fig-row"><div>
<svg id="rep-hist" role="img" aria-label="Histogram of difference-in-means estimates from repeated trials, centered on the true effect of 15 metres."></svg>
<svg id="rep-ladder" role="img" aria-label="95% confidence intervals from the most recent 20 repeated trials, drawn as horizontal segments against the true effect."></svg>
${legend([["var(--or)", "bar", "Difference in means (unadjusted)"], ["var(--green)", "line", "True effect, 15 m", "6 4"], ["var(--red)", "line", "Interval that misses"]])}
<div id="rep-player"></div></div>
<div><div class="fig-readout" id="rep-readout"></div></div></div>
<p class="fig-caption" id="rep-caption"></p></div>
<p>Each 95% interval reaches about ${fmt(1.96 * Math.sqrt(4 / R.DEFAULTS.n) * M, 0)} metres on either side of its estimate, more than the effect itself. More than half of these trials would fail to show a significant benefit. The rest of this lesson makes that interval narrower without changing what it estimates and without giving up randomization's guarantee.</p>
</section>

<section class="lab-step" data-title="Adjust for a prognostic covariate"><h2 tabindex="-1">Use what you knew at baseline</h2>
<p>Much of the spread in walk-distance change is predictable from things measured before randomization, such as the baseline walk distance itself. Call that baseline covariate X. Standardization (also called g-computation) uses it in three moves:</p>
<ol><li>In each arm, fit an outcome model: predicted change given X.</li><li>For <em>every</em> patient in the trial, predict the outcome under the device and under control.</li><li>Average the difference over everyone.</li></ol>
<p>The target has not changed. It is still the average effect over the whole trial population, the same marginal quantity the difference in means estimates. The model is a tool for removing predictable noise, not a new question.</p>
<div class="predict" data-options="About 20 patients|About 100 patients|About 200 patients" data-answer="2" data-hint="Adjustment divides the variance by about 1 − R² = 0.5, so 200 adjusted patients do the work of 400 unadjusted ones: 200 extra.">X explains half of the outcome variance (R² = 0.5). The trial has 200 patients. How many extra unadjusted patients would give the same precision as adjusting?</div>
<label><span>How prognostic is X? Share of outcome variance it explains, R² = <strong class="rct-v" id="r2-v"></strong></span> <input id="r2" type="range" min="0" max="0.8" step="0.1"></label>
<div class="figure"><div class="fig-row"><div>
<svg id="std-scatter" role="img" aria-label="One simulated trial: each patient's baseline covariate against walk-distance change, colored by arm, with a fitted line per arm."></svg>
${legend([["var(--p)", "dot", "Device arm"], ["var(--teal)", "dot", "Control arm"], ["var(--p)", "line", "Device fit"], ["var(--teal)", "line", "Control fit", "6 4"]])}
</div><div><div class="fig-readout" id="std-readout"></div></div></div>
<p class="fig-caption" id="std-caption"></p></div>
<div class="figure"><div class="fig-row"><div>
<svg id="ci-pair" role="img" aria-label="Two 95% confidence intervals from the same trial: unadjusted and standardized, against the true effect."></svg>
<svg id="adj-hist" role="img" aria-label="Histograms of unadjusted and standardized estimates over 4000 repeated trials; both are centered on the truth and the standardized one is narrower."></svg>
${legend([["var(--or)", "line", "Unadjusted, 4000 trials"], ["var(--purple)", "bar", "Standardized, 4000 trials"], ["var(--green)", "line", "True effect", "6 4"]])}
</div><div>
<div class="rct-meter" id="meter" role="group" aria-label="Precision gain from adjustment as extra patients"></div>
<div class="fig-readout" id="adj-readout"></div></div></div>
<p class="fig-caption" id="adj-caption"></p></div>
<p class="math">extra patients ≈ n · R² / (1 − R²)</p>
<p>That rule is exact in large samples for a correctly specified linear adjustment with a constant effect, for any allocation ratio: adjustment divides the variance by 1 − R², so n adjusted patients match n / (1 − R²) unadjusted ones. The simulated number beside it is from 4000 repeated trials and carries Monte Carlo error of a few percent.</p>
</section>

<section class="lab-step" data-title="A wrong model stays centered"><h2 tabindex="-1">The outcome model can be wrong</h2>
<p>Suppose the true relation between baseline and outcome curves: patients who start near the ceiling gain less. A straight line is then the wrong model. Does a wrong model bias the adjusted estimate?</p>
<div class="predict" data-options="Yes, the estimates shift away from 15 m|No, they stay centered; only the precision gain shrinks|They become wider than the unadjusted estimates" data-answer="1" data-hint="Randomization, not the outcome model, carries validity. A poor model captures less of the outcome variance, so it buys less precision.">Truth is curved; you fit a straight line in each arm. What happens to the standardized estimates over repeated trials?</div>
<label><span>How curved is the true relation? Share of X's prognostic signal that is curved: <strong class="rct-v" id="curve-v"></strong></span> <input id="curve" type="range" min="0" max="1" step="0.25"></label>
<label>Working outcome model in each arm <select id="model"><option value="linear">Straight line in X</option><option value="quadratic">Line plus X² (correct shape)</option><option value="sign">Crude: only whether X is above average</option></select></label>
<div class="figure"><div class="fig-row"><div>
<svg id="shape" role="img" aria-label="The true prognostic curve against the best version of the chosen working model."></svg>
${legend([["var(--green)", "line", "True mean of Y(0) given X", "6 4"], ["var(--purple)", "line", "Best fit of the working model"]])}
<svg id="curve-hist" role="img" aria-label="Histograms of unadjusted and standardized estimates over 4000 repeated trials under the chosen truth and model."></svg>
${legend([["var(--or)", "line", "Unadjusted"], ["var(--purple)", "bar", "Standardized with the working model"], ["var(--green)", "line", "True effect", "6 4"]])}
</div><div><div class="fig-readout" id="curve-readout"></div></div></div>
<p class="fig-caption" id="curve-caption"></p></div>
<p><strong>Why it stays centered.</strong> In a randomized trial the chance of receiving the device is known by design (here exactly ½). Standardization is then exactly AIPW, augmented inverse probability weighting, with that known propensity:</p>
<p class="math">ψ̂ = mean(m̂₁ − m̂₀) + mean(A(Y − m̂₁)/π) − mean((1 − A)(Y − m̂₀)/(1 − π))</p>
<p>With an intercept in each arm's model, each arm's residuals average exactly zero, so both correction terms vanish and AIPW equals the standardized estimate you computed. AIPW stays consistent if <em>either</em> the outcome model or the propensity is right, and randomization makes the propensity right. The geometry lessons explain why a wrong outcome model then costs only precision; <a href="01-one-step-estimator.html">the one-step estimator</a> is where AIPW first appears.</p>
<p class="note">In finite samples the standardized estimator has a bias of order 1/n from estimating the slopes. It is invisible here: the simulated bias is within about two Monte Carlo standard errors of zero for every setting.</p>
</section>

<section class="lab-step" data-title="Binary outcomes: which odds ratio?"><h2 tabindex="-1">Binary outcomes: an adjusted odds ratio answers a different question</h2>
<p>Now make the outcome binary: a responder is someone whose walk distance improves by at least 30 metres. X is also binary: milder disease at baseline (half the patients) or not. Randomization is perfect, so X is balanced between arms and there is no confounding at all.</p>
<p>A logistic regression of response on arm and X reports exp(β̂), where β̂ is the arm coefficient: the odds ratio <em>within</em> a level of X. The odds ratio for the whole trial population is a different number whenever X predicts the outcome. This is non-collapsibility: odds ratios do not average like risks do.</p>
<div class="predict" data-options="The marginal odds ratio for the whole population|A larger odds ratio, the one within each X stratum|The risk difference" data-answer="1" data-hint="The logistic coefficient estimates the conditional odds ratio, which is farther from 1 than the marginal one whenever X is prognostic. No confounding is needed for the gap.">In this perfectly randomized trial, with X strongly prognostic, what is the logistic model's device odds ratio, exp(β̂), centered on?</div>
<label><span>How strongly does X shift the odds of response? Log-odds gap between X levels: <strong class="rct-v" id="gap-v"></strong></span> <input id="gap" type="range" min="0" max="3" step="0.5"></label>
<label>Odds ratio for the device within each level of X <select id="or"><option value="1.5">1.5</option><option value="2">2</option><option value="3">3</option><option value="5">5</option></select></label>
<div class="figure"><div class="fig-row"><div>
<svg id="or-chart" role="img" aria-label="Odds ratios on a log scale: the two stratum odds ratios, and the average over 1000 simulated trials of the unadjusted, logistic-coefficient and standardized odds ratios, against the conditional and marginal truths."></svg>
${legend([["var(--ink)", "line", "Conditional OR (within X)", "2 3"], ["var(--green)", "line", "Marginal OR (whole population)", "6 4"], ["var(--or)", "dot", "Unadjusted"], ["var(--phat)", "dot", "Logistic coefficient"], ["var(--purple)", "dot", "Standardized"]])}
</div><div><div class="fig-readout" id="or-readout"></div></div></div>
<p class="fig-caption" id="or-caption"></p></div>
<div id="or-table"></div>
<p>Standardization fixes this without abandoning the logistic model: predict every patient's response probability with A set to 1 and to 0, average each over the trial, and form the risk difference, risk ratio or odds ratio from those two averages. The result estimates the marginal effect, the same target as the unadjusted comparison, with a narrower interval. The FDA's 2023 final guidance on covariate adjustment makes exactly this distinction between conditional and unconditional treatment effects.</p>
</section>

<section class="lab-step" data-title="Standard errors that survive"><h2 tabindex="-1">A standard error that does not trust the model</h2>
<p>The usual ANCOVA analysis fits one linear model, Y on arm and X with a common slope, and reports the arm coefficient with the model's standard error. That standard error assumes the model: one slope, one residual variance. When the device's benefit varies with baseline, both assumptions fail.</p>
<p>The standardized estimator has its own standard error that makes no such assumption. Each patient contributes one number, their influence-function value</p>
<p class="math">φ̂ᵢ = Aᵢ(Yᵢ − m̂₁(Xᵢ))/π − (1 − Aᵢ)(Yᵢ − m̂₀(Xᵢ))/(1 − π) + m̂₁(Xᵢ) − m̂₀(Xᵢ) − ψ̂<br>SE = √( Σ φ̂ᵢ² ) / n</p>
<p>and the standard error is just their spread divided by √n. (Here each arm's residual part gets the usual n<sub>a</sub>/(n<sub>a</sub> − 2) degrees-of-freedom factor.) The later lessons show where φ comes from.</p>
<div class="predict" data-options="About 95%, as advertised|Noticeably less, under 90%|More than 99%" data-answer="1" data-hint="With unequal allocation and a heterogeneous effect, the common-slope model misjudges the variance. The influence-function interval stays near 95%.">One device patient for every three controls, and the device helps more for patients with higher baseline X. How often does the ANCOVA model-based 95% interval cover the true effect?</div>
<label>Allocation, device : control <select id="pi"><option value="0.25">1 : 3</option><option value="0.5">1 : 1</option><option value="0.75">3 : 1</option></select></label>
<label><span>How much the device effect varies with baseline: extra metres per SD of X: <strong class="rct-v" id="het-v"></strong></span> <input id="het" type="range" min="0" max="2" step="0.5"></label>
<div class="figure"><div class="fig-row"><div>
<svg id="cov-chart" role="img" aria-label="Coverage of nominal 95% intervals over 4000 repeated trials for three analyses, with Monte Carlo error bars and a reference line at 95%."></svg>
${legend([["var(--or)", "dot", "Unadjusted, Welch SE"], ["var(--red)", "dot", "ANCOVA, model-based SE"], ["var(--purple)", "dot", "Standardized, influence-function SE"], ["var(--muted)", "line", "95%", "5 4"]])}
</div><div><div class="fig-readout" id="cov-readout"></div></div></div>
<p class="fig-caption" id="cov-caption"></p></div>
<div id="cov-table"></div>
<p>With 1 : 1 allocation the ANCOVA model-based standard error happens to remain valid (or conservative) in large samples even when the model is wrong, which is why it has served trials well. Move the allocation away from 1 : 1 and it no longer does. The FDA guidance asks for standard errors that remain valid under misspecification, such as robust (sandwich) standard errors, and for covariates that are prespecified and few relative to the sample size.</p>
</section>

<section class="lab-step" data-title="One score from history"><h2 tabindex="-1">One covariate that summarizes many: a prognostic score</h2>
<p>Real trials record many baseline variables. Adjusting for all of them costs degrees of freedom and still misses curves and interactions. Another route: learn a <em>prognostic score</em> from historical patients, the predicted outcome under control given all baseline variables, and adjust for that one number. This is the PROCOVA idea, which the EMA qualified in 2022 for phase 2 and 3 trials with continuous outcomes.</p>
<p>Here the outcome depends on 10 baseline variables, with one curved effect and one interaction. The score is a regression fitted to control patients from past studies, frozen before the trial starts.</p>
<label>Historical patients used to learn the score <select id="nhist">${G.nHist.map((v) => `<option value="${v}">${v}</option>`).join("")}</select></label>
<div class="figure"><div class="fig-row"><div>
<svg id="ess-chart" role="img" aria-label="Effective sample size of four analyses of the same 200-patient trials: unadjusted, all 10 covariates, the learned prognostic score, and the true prognostic function."></svg>
</div><div><div class="fig-readout" id="ess-readout"></div></div></div>
<p class="fig-caption" id="ess-caption"></p></div>
<div id="ess-table"></div>
<p>The score is computed from baseline data only and fixed in advance, so it is just another prespecified baseline covariate. A poor score costs precision, never validity: with 20 historical patients it helps less than the raw covariates, yet every analysis stays centered on the truth. The gain depends on how well history transfers to the new trial population, which the qualification opinion asks sponsors to justify.</p>
<p class="note"><strong>What is exact, simulated and schematic.</strong> The binary odds ratios in the table are exact calculations. Every histogram, coverage and effective sample size comes from seeded repeated trials (4000 per setting for continuous outcomes, 1000 for binary and PROCOVA) precomputed by <code>science/rct-adjustment.js</code>; Monte Carlo error is shown. The device, the outcome scale and the data-generating rules are a teaching world, not a real trial.</p>
</section>`;

  const SEL = [
    ["model", "model", String],
    ["or", "or", Number],
    ["pi", "pi", Number],
    ["nhist", "nHist", Number],
  ];
  control(byId("r2"), state, "r2");
  control(byId("curve"), state, "curve");
  control(byId("gap"), state, "gap");
  control(byId("het"), state, "het");
  SEL.forEach(([id, key, cast]) => {
    const e = byId(id),
      read = () => (e.value = String(state.get()[key]));
    read();
    state.subscribe(read);
    e.addEventListener("change", () => state.set({ [key]: cast(e.value) }));
  });

  let D = null;
  const truth = R.DEFAULTS.tau,
    X0 = R.HIST.min * M,
    X1 = R.HIST.max * M,
    BW = ((R.HIST.max - R.HIST.min) / R.HIST.bins) * M,
    centers = () => Array.from({ length: R.HIST.bins }, (_, i) => X0 + (i + 0.5) * BW);

  /* Histogram of estimates in metres; returns the plot. */
  function histPlot(svg, layers, height = 230, ymaxFixed = null) {
    const ymax = ymaxFixed || Math.max(...layers.flatMap((l) => l.counts)) * 1.08 || 1,
      plot = mkPlot(svg, {
        x: [X0, X1], y: [0, ymax], height, xticks: effectTicks(svg),
        margin: { l: 54, r: 18, t: 22, b: 46 },
        xlabel: "Estimated effect, m", ylabel: "Trials",
        tickFormat: (v) => fmt(v, 0),
      }),
      c = centers();
    layers.forEach((l) => {
      if (l.kind === "bar")
        plot.bars(c.map((x, i) => [x, l.counts[i]]), BW * 0.92, { fill: l.color, "fill-opacity": 0.5 });
      else {
        const pts = [[X0, 0]];
        c.forEach((x, i) => pts.push([x - BW / 2, l.counts[i]], [x + BW / 2, l.counts[i]]));
        pts.push([X1, 0]);
        plot.line(pts, { stroke: l.color, "stroke-width": 2 });
      }
    });
    plot.vline(truth * M, { stroke: "var(--green)", "stroke-width": 2, "stroke-dasharray": "6 4" });
    return plot;
  }

  /* ---------- step 1: repeated trials ---------- */
  let repK = 1;
  function drawRepeats() {
    const L = D.ladder,
      k = Math.max(1, Math.min(L.est.length, repK)),
      est = L.est.slice(0, k),
      se = L.se.slice(0, k),
      hist = R.bin(est),
      ymax = Math.max(12, ...R.bin(L.est).counts) * 1.08;
    histPlot(byId("rep-hist"), [{ counts: hist.counts, kind: "bar", color: "var(--or)" }], 220, ymax);
    const first = Math.max(0, k - 20),
      rows = est.slice(first).map((e, j) => ({ e, s: se[first + j], i: first + j + 1 })),
      lad = mkPlot(byId("rep-ladder"), {
        x: [X0, X1], y: [0, 21], height: 250, xticks: effectTicks(byId("rep-ladder")),
        margin: { l: 54, r: 18, t: 10, b: 46 },
        xlabel: "95% interval from each trial, m", yticks: [], grid: false,
        tickFormat: (v) => fmt(v, 0),
      }),
      g = lad.layer("ladder");
    lad.vline(truth * M, { stroke: "var(--green)", "stroke-width": 2, "stroke-dasharray": "6 4" });
    rows.forEach((r, j) => {
      const lo = (r.e - R.Z * r.s) * M,
        hi = (r.e + R.Z * r.s) * M,
        miss = lo > truth * M || hi < truth * M,
        col = miss ? "var(--red)" : "var(--or)",
        y = lad.sy(20 - j);
      g.append(
        el("line", { x1: lad.sx(Math.max(X0, lo)), x2: lad.sx(Math.min(X1, hi)), y1: y, y2: y, stroke: col, "stroke-width": 2.5, "stroke-linecap": "round" }),
        el("circle", { cx: lad.sx(r.e * M), cy: y, r: 3.5, fill: col }),
      );
    });
    lad.fg.append(el("text", { class: "fig-text", x: 8, y: lad.sy(20) + 4 }, `#${rows[0].i}`));
    lad.fg.append(el("text", { class: "fig-text", x: 8, y: lad.sy(21 - rows.length) + 4 }, `#${rows.at(-1).i}`));
    const covered = est.filter((e, i) => Math.abs(e - truth) <= R.Z * se[i]).length,
      sig = est.filter((e, i) => e - R.Z * se[i] > 0).length;
    readout("rep-readout", [
      ["trials run", k],
      ["mean estimate", m(R.mean(est)) + " m"],
      ["truth", m(truth) + " m"],
      ["SD across trials", k > 1 ? m(Math.sqrt(R.variance(est))) + " m" : "needs 2 trials"],
      ["typical ±1.96·SE", m(R.Z * R.mean(se)) + " m"],
      ["intervals covering", `${covered} of ${k} (${pct(covered / k, 0)})`],
      ["significant at 5%", `${sig} of ${k} (${pct(sig / k, 0)})`],
    ]);
    byId("rep-caption").textContent =
      k < 2
        ? `Trial #1 estimates ${m(est[0])} m (95% interval ${m(est[0] - R.Z * se[0])} to ${m(est[0] + R.Z * se[0])} m). Press Play to repeat the trial with new patients.`
        : `After ${k} repeated trials the estimates average ${m(R.mean(est))} m against a truth of 15 m, but single trials range from ${m(Math.min(...est), 0)} to ${m(Math.max(...est), 0)} m. ${covered} of ${k} intervals cover the truth; only ${pct(sig / k, 0)} of trials would declare a benefit.`;
  }
  const repPlayer = player(byId("rep-player"), {
    duration: 8000,
    label: "Repeated trials",
    formatValue: (t) => String(Math.max(1, Math.round(t * G.ladder))),
    onT(t) {
      repK = Math.max(1, Math.round(t * G.ladder));
      if (D) drawRepeats();
    },
  });

  /* ---------- step 2: standardization ---------- */
  function drawAdjust() {
    const r2 = nearest(G.r2, state.get().r2),
      E = D.adjust.find((e) => e.r2 === r2),
      d = R.trial({ r2 }, S.rng(G.seed)),
      u = R.unadjusted(d),
      s = R.standardized(d, "linear"),
      ys = d.y.map((v) => v * M),
      ylo = Math.floor(Math.min(...ys) / 50) * 50,
      yhi = Math.ceil(Math.max(...ys) / 50) * 50,
      sc = mkPlot(byId("std-scatter"), {
        x: [-3, 3], y: [ylo, yhi], height: 300,
        margin: { l: 58, r: 18, t: 22, b: 46 },
        xlabel: "Baseline covariate X, SD from the mean", ylabel: "Walk change, m",
        tickFormat: (v) => fmt(v, 0),
      }),
      dots = sc.layer("dots");
    d.x.forEach((x, i) =>
      dots.append(el("circle", {
        cx: sc.sx(Math.max(-3, Math.min(3, x))), cy: sc.sy(ys[i]), r: 3.2,
        fill: d.a[i] ? "var(--p)" : "var(--teal)", "fill-opacity": 0.55,
      })),
    );
    const line = (fit) => [-3, 3].map((x) => [x, fit.predict([1, x]) * M]);
    sc.line(line(s.fit0), { stroke: "var(--teal)", "stroke-width": 3, "stroke-dasharray": "8 5" });
    sc.line(line(s.fit1), { stroke: "var(--p)", "stroke-width": 3 });
    const mu1 = R.mean(s.m1),
      mu0 = R.mean(s.m0);
    const xd = R.mean(d.x.filter((_, i) => d.a[i])),
      xc = R.mean(d.x.filter((_, i) => !d.a[i]));
    readout("std-readout", [
      ["R² of X", fx(r2, 1)],
      ["mean X, device", fx(xd, 2)],
      ["mean X, control", fx(xc, 2)],
      ["device arm mean", m(R.mean(d.y.filter((_, i) => d.a[i]))) + " m"],
      ["control arm mean", m(R.mean(d.y.filter((_, i) => !d.a[i]))) + " m"],
      ["all on device", m(mu1) + " m"],
      ["all on control", m(mu0) + " m"],
      ["standardized", m(s.est) + " m"],
      ["unadjusted", m(u.est) + " m"],
    ]);
    const imbalance = Math.abs(xd - xc) >= 0.1 && r2 > 0 && Math.abs(u.est - truth) > Math.abs(s.est - truth);
    byId("std-caption").textContent =
      `One trial of 200. The lines are the arm-specific fits. Predicting all 200 patients under the device averages ${m(mu1)} m ("all on device"), under control ${m(mu0)} m; the standardized effect is the difference, ${m(s.est)} m. The raw difference in arm means is ${m(u.est)} m.` +
      (imbalance
        ? ` By chance the device arm started ${xd > xc ? "higher" : "lower"} on X (mean ${fx(xd, 2)} against ${fx(xc, 2)} SD); adjustment removes that chance imbalance, which is where much of the unadjusted error came from.`
        : "");

    // Interval pair for this trial.
    const ci = mkPlot(byId("ci-pair"), {
        x: [X0, X1], y: [0, 3], height: 150, xticks: effectTicks(byId("ci-pair")),
        margin: { l: 128, r: 18, t: 12, b: 46 },
        xlabel: "95% interval from this trial, m", yticks: [], grid: false,
        tickFormat: (v) => fmt(v, 0),
      }),
      rows = [["Unadjusted", u, "var(--or)", 2], ["Standardized", s, "var(--purple)", 1]];
    ci.vline(truth * M, { stroke: "var(--green)", "stroke-width": 2, "stroke-dasharray": "6 4" });
    rows.forEach(([name, r, col, yv]) => {
      const y = ci.sy(yv);
      ci.marks.append(
        el("line", { x1: ci.sx(Math.max(X0, (r.est - R.Z * r.se) * M)), x2: ci.sx(Math.min(X1, (r.est + R.Z * r.se) * M)), y1: y, y2: y, stroke: col, "stroke-width": 5, "stroke-linecap": "round" }),
        el("circle", { cx: ci.sx(r.est * M), cy: y, r: 6, fill: col, stroke: "var(--paper)", "stroke-width": 2 }),
      );
      ci.fg.append(el("text", { class: "fig-text ink", x: ci.m.l - 10, y: y + 5, "text-anchor": "end" }, name));
    });
    histPlot(byId("adj-hist"), [
      { counts: E.histAdj.counts, kind: "bar", color: "var(--purple)" },
      { counts: E.histUnadj.counts, kind: "line", color: "var(--or)" },
    ]);
    // Meter: equivalent unadjusted sample size.
    const n = R.DEFAULTS.n,
      extra = E.theoryExtra,
      scaleMax = 1000,
      w = (v) => Math.min(100, (v / scaleMax) * 100);
    byId("meter").innerHTML =
      `<div class="rct-meter-head">Adjustment is worth <strong>+${extra}</strong> patients</div>` +
      `<div class="rct-meter-bar" aria-hidden="true"><i class="base" style="width:${w(n)}%"></i><i class="gain" style="width:${w(extra)}%"></i></div>` +
      `<div class="rct-meter-scale" aria-hidden="true"><span>0</span><span>500</span><span>1000 patients</span></div>` +
      `<p>200 adjusted patients give the precision of about <strong>${n + extra}</strong> unadjusted ones. Simulated: +${E.extraPatients}.</p>`;
    readout("adj-readout", [
      ["unadjusted", `${m(u.est)} ± ${m(R.Z * u.se)} m`],
      ["standardized", `${m(s.est)} ± ${m(R.Z * s.se)} m`],
      ["SD, unadjusted", m(E.unadjusted.sd) + " m"],
      ["SD, standardized", m(E.standardized.sd) + " m"],
      ["mean, unadjusted", m(E.unadjusted.mean, 2) + " m"],
      ["mean, standardized", m(E.standardized.mean, 2) + " m"],
      ["variance ratio", fx(E.varianceRatio, 2)],
      ["1/(1 − R²)", fx(1 / (1 - r2), 2)],
      ["coverage (adj.)", pct(E.standardized.coverage)],
    ]);
    byId("adj-caption").textContent =
      r2 === 0
        ? "With R² = 0, X carries no information: the two histograms coincide and adjustment is worth nothing (it also costs almost nothing)."
        : `Both histograms center on 15 m (means ${m(E.unadjusted.mean, 1)} and ${m(E.standardized.mean, 1)} m over 4000 trials). The standardized SD is ${m(E.standardized.sd)} m against ${m(E.unadjusted.sd)} m unadjusted: the interval is ${pct(1 - E.standardized.sd / E.unadjusted.sd, 0)} narrower.`;
  }

  /* ---------- step 3: wrong working model ---------- */
  function drawCurve() {
    const c = nearest(G.curve, state.get().curve),
      model = state.get().model,
      E = D.curve.find((e) => e.curve === c && e.model === model),
      r2 = G.curveR2,
      a = Math.sqrt(r2 * (1 - c)),
      xs = Array.from({ length: 121 }, (_, i) => -2.5 + (5 * i) / 120),
      truthCurve = xs.map((x) => [x, R.prognostic(x, r2, c) * M]),
      fitAt = (x) =>
        model === "quadratic" ? R.prognostic(x, r2, c)
        : model === "linear" ? a * x
        : a * Math.sqrt(2 / Math.PI) * (x > 0 ? 1 : -1),
      fitted = model === "sign"
        ? [[-2.5, fitAt(-1) * M], [0, fitAt(-1) * M], [0, fitAt(1) * M], [2.5, fitAt(1) * M]]
        : xs.map((x) => [x, fitAt(x) * M]),
      all = [...truthCurve, ...fitted].map((p) => p[1]),
      lo = Math.floor(Math.min(...all) / 20) * 20,
      hi = Math.ceil(Math.max(...all) / 20) * 20 || 20,
      p = mkPlot(byId("shape"), {
        x: [-2.5, 2.5], y: [lo, hi], height: 240,
        margin: { l: 58, r: 18, t: 22, b: 46 },
        xlabel: "Baseline covariate X, SD from the mean", ylabel: "Mean of Y(0), m",
        tickFormat: (v) => fmt(v, 1),
      });
    p.line(truthCurve, { stroke: "var(--green)", "stroke-dasharray": "7 5" });
    p.line(fitted, { stroke: "var(--purple)" });
    histPlot(byId("curve-hist"), [
      { counts: E.histAdj.counts, kind: "bar", color: "var(--purple)" },
      { counts: E.histUnadj.counts, kind: "line", color: "var(--or)" },
    ]);
    const S2 = E.standardized;
    readout("curve-readout", [
      ["R² of the truth", fx(r2, 1)],
      ["captured by model", fx(E.captured, 2)],
      ["mean, standardized", m(S2.mean, 2) + " m"],
      ["bias ± MC SE", `${m(S2.bias, 2)} ± ${m(S2.mcse, 2)} m`],
      ["SD, unadjusted", m(E.unadjusted.sd) + " m"],
      ["SD, standardized", m(S2.sd) + " m"],
      ["worth, simulated", `${E.extraPatients >= 0 ? "+" : ""}${E.extraPatients} patients`],
      ["worth, formula", `+${E.theoryExtra} patients`],
      ["coverage", pct(S2.coverage)],
    ]);
    const names = { linear: "A straight line", quadratic: "The correct curved model", sign: "The crude above/below model" };
    byId("curve-caption").textContent =
      `${names[model]} captures R² = ${fx(E.captured, 2)} of the ${fx(r2, 1)} available. The standardized estimates stay centered (mean ${m(S2.mean, 1)} m, truth 15 m) and are worth ${Math.max(0, E.extraPatients)} extra patients` +
      (E.captured < 0.005 ? ": the model explains nothing, so it buys nothing, and it still does no harm." : ".");
  }

  /* ---------- step 4: binary outcome, non-collapsibility ---------- */
  function drawBinary() {
    const gap = nearest(G.binaryGap, state.get().gap),
      or = nearest(G.binaryOR, state.get().or),
      W = R.binaryWorld({ gap, logOR: Math.log(or) }),
      E = D.binary.find((e) => e.gap === gap && e.or === or),
      ticksOR = (narrow(byId("or-chart")) ? [1, 2, 3, 5] : [1, 1.5, 2, 3, 5, 8]).filter((v) => v <= or * 1.6),
      x0 = Math.log(0.9),
      x1 = Math.log(or * 1.6),
      p = mkPlot(byId("or-chart"), {
        x: [x0, x1], y: [0, 6], height: 270,
        margin: { l: 132, r: 18, t: 14, b: 46 },
        xlabel: "Odds ratio (log scale)", yticks: [], grid: false,
        xticks: ticksOR.map(Math.log), tickFormat: (v) => fmt(Math.exp(v), 1),
      }),
      rows = [
        ["Stratum X = 0", W.strata[0].or, "var(--ink)", true],
        ["Stratum X = 1", W.strata[1].or, "var(--ink)", true],
        ["Unadjusted", E.unadjustedOR, "var(--or)"],
        ["Logistic coef.", E.conditionalOR, "var(--phat)"],
        ["Standardized", E.standardizedOR, "var(--purple)"],
      ];
    p.vline(Math.log(W.conditionalOR), { stroke: "var(--ink)", "stroke-dasharray": "2 3", opacity: 0.8 });
    p.vline(Math.log(W.marginalOR), { stroke: "var(--green)", "stroke-width": 2, "stroke-dasharray": "6 4" });
    rows.forEach(([name, v, col, exact], j) => {
      const y = p.sy(5.2 - j);
      p.marks.append(
        el("line", { x1: p.sx(x0), x2: p.sx(Math.log(v)), y1: y, y2: y, stroke: "var(--grid)", "stroke-width": 1.5 }),
        exact
          ? el("rect", { x: p.sx(Math.log(v)) - 5, y: y - 5, width: 10, height: 10, fill: "none", stroke: col, "stroke-width": 2 })
          : el("circle", { cx: p.sx(Math.log(v)), cy: y, r: 6.5, fill: col, stroke: "var(--paper)", "stroke-width": 2 }),
      );
      p.fg.append(el("text", { class: "fig-text ink", x: p.m.l - 10, y: y + 5, "text-anchor": "end" }, name));
    });
    readout("or-readout", [
      ["conditional OR", fx(W.conditionalOR, 2) + " exact"],
      ["marginal OR", fx(W.marginalOR, 2) + " exact"],
      ["marginal RD", pct(W.marginalRD) + " exact"],
      ["unadjusted OR", fx(E.unadjustedOR, 2) + " sim"],
      ["logistic exp(β̂)", fx(E.conditionalOR, 2) + " sim"],
      ["standardized OR", fx(E.standardizedOR, 2) + " sim"],
      ["RD SD, unadjusted", pct(E.unadjustedRD.sd)],
      ["RD SD, standardized", pct(E.standardizedRD.sd)],
    ]);
    const gain = Math.round(G.binaryN * ((E.unadjustedRD.sd / E.standardizedRD.sd) ** 2 - 1));
    byId("or-caption").textContent =
      gap === 0
        ? `With a gap of 0, X does not predict response, and conditional and marginal odds ratios coincide at ${fx(or, 1)}. Collapsibility returns only in this boundary case (or when the device has no effect).`
        : `Squares are exact stratum odds ratios, both ${fx(or, 1)}. Yet the whole-population odds ratio is ${fx(W.marginalOR, 2)}, with no confounding anywhere. Over 1000 simulated trials of 400 patients, the logistic coefficient averages ${fx(E.conditionalOR, 2)} (the conditional target), while standardizing the same logistic model averages ${fx(E.standardizedOR, 2)} (the marginal target, like the unadjusted ${fx(E.unadjustedOR, 2)}). Averages are geometric means. For the risk difference, standardization is worth about ${Math.max(0, gain)} extra patients.`;
    byId("or-table").innerHTML = table(
      ["Group", "Control", "Device", "RD", "OR"],
      [
        ["X = 0", pct(W.strata[0].risk0), pct(W.strata[0].risk1), pct(W.strata[0].rd), fx(W.strata[0].or, 3)],
        ["X = 1", pct(W.strata[1].risk0), pct(W.strata[1].risk1), pct(W.strata[1].rd), fx(W.strata[1].or, 3)],
        ["Everyone", pct(W.risk0), pct(W.risk1), pct(W.marginalRD), fx(W.marginalOR, 3)],
      ],
      "Exact response probabilities, risk difference (RD) and odds ratio (OR)",
    );
  }

  /* ---------- step 5: coverage ---------- */
  function drawCoverage() {
    const pi = nearest(G.pi, state.get().pi),
      het = nearest(G.het, state.get().het),
      E = D.se.find((e) => e.pi === pi && e.het === het),
      rows = [
        ["Unadjusted", E.unadjusted, "var(--or)"],
        ["ANCOVA, model SE", E.ancova, "var(--red)"],
        ["Standardized, IF SE", E.standardized, "var(--purple)"],
      ],
      p = mkPlot(byId("cov-chart"), {
        x: [0.8, 1], y: [0, 3.6], height: 210,
        margin: { l: 164, r: 18, t: 14, b: 46 },
        xlabel: "Coverage of 95% intervals", yticks: [], grid: false,
        xticks: narrow(byId("cov-chart")) ? [0.8, 0.9, 1] : [0.8, 0.85, 0.9, 0.95, 1], tickFormat: (v) => fx(v * 100, 0) + "%",
      });
    p.vline(0.95, { stroke: "var(--muted)" });
    rows.forEach(([name, s, col], j) => {
      const y = p.sy(3 - j),
        c = Math.max(0.8, s.coverage),
        w = 1.96 * s.coverageMCSE;
      p.marks.append(
        el("line", { x1: p.sx(Math.max(0.8, c - w)), x2: p.sx(Math.min(1, c + w)), y1: y, y2: y, stroke: col, "stroke-width": 2.5 }),
        el("circle", { cx: p.sx(c), cy: y, r: 6.5, fill: col, stroke: "var(--paper)", "stroke-width": 2 }),
      );
      p.fg.append(el("text", { class: "fig-text ink", x: p.m.l - 10, y: y + 5, "text-anchor": "end" }, name));
    });
    const ratio = { 0.25: "1 : 3", 0.5: "1 : 1", 0.75: "3 : 1" }[pi];
    readout("cov-readout", [
      ["allocation", ratio],
      ["effect slope", m(het, 0) + " m per SD"],
      ["ANCOVA coverage", pct(E.ancova.coverage)],
      ["IF coverage", pct(E.standardized.coverage)],
      ["MC error (2 SE)", "± " + pct(1.96 * E.ancova.coverageMCSE)],
      ["ANCOVA SD / SE", `${m(E.ancova.sd)} / ${m(E.ancova.meanSE)} m`],
      ["IF SD / SE", `${m(E.standardized.sd)} / ${m(E.standardized.meanSE)} m`],
    ]);
    byId("cov-caption").textContent =
      `Over 4000 trials (whiskers: ±2 Monte Carlo SE). The ANCOVA estimates actually vary with SD ${m(E.ancova.sd)} m, but its model-based SE averages ${m(E.ancova.meanSE)} m, so its intervals cover ${pct(E.ancova.coverage)} of the time. The influence-function SE averages ${m(E.standardized.meanSE)} m against an actual SD of ${m(E.standardized.sd)} m: coverage ${pct(E.standardized.coverage)}.`;
    byId("cov-table").innerHTML = table(
      ["Analysis", "Mean, m", "SD, m", "Avg SE, m", "Cover"],
      rows.map(([name, s]) => [name, m(s.mean, 2), m(s.sd, 2), m(s.meanSE, 2), pct(s.coverage)]),
      "4000 repeated trials, truth 15 m: mean estimate, SD across trials, average reported SE, coverage",
    );
  }

  /* ---------- step 6: prognostic score ---------- */
  function drawProcova() {
    const h = nearest(G.nHist, state.get().nHist),
      E = D.procova.find((e) => e.nHist === h),
      n = R.DEFAULTS.n,
      rows = [
        ["Unadjusted", E.unadj, "var(--or)"],
        ["10 covariates", E.all, "var(--teal)"],
        ["Learned score", E.score, "var(--purple)"],
        ["True score", E.oracle, "var(--green)"],
      ],
      ess = rows.map(([, s]) => n + s.extraPatients),
      xmax = Math.ceil((Math.max(...ess) * 1.25) / 100) * 100,
      p = mkPlot(byId("ess-chart"), {
        x: [0, xmax], y: [0, 4.4], height: 240,
        margin: { l: 164, r: 18, t: 14, b: 46 },
        xlabel: narrow(byId("ess-chart")) ? "Effective sample size" : "Effective sample size (unadjusted patients, same precision)", yticks: [], grid: true,
        tickFormat: (v) => fmt(v, 0),
      });
    rows.forEach(([name, s, col], j) => {
      const y = p.sy(3.8 - j),
        e = n + s.extraPatients;
      p.marks.append(el("rect", { x: p.sx(0), y: y - 11, width: p.sx(e) - p.sx(0), height: 22, rx: 3, fill: col, "fill-opacity": 0.75 }));
      p.fg.append(
        el("text", { class: "fig-text ink", x: p.m.l - 10, y: y + 5, "text-anchor": "end" }, name),
        el("text", { class: "fig-text", x: p.sx(e) + 6, y: y + 5 }, String(e)),
      );
    });
    readout("ess-readout", [
      ["historical n", h],
      ["score R²", fx(E.scoreR2, 2)],
      ["best possible R²", fx(E.oracleR2, 2)],
      ["score: extra n", "+" + E.score.extraPatients],
      ["10 covariates", "+" + E.all.extraPatients],
      ["score bias", `${m(E.score.bias, 2)} m`],
      ["MC SE of bias", `${m(E.score.mcse, 2)} m`],
      ["score coverage", pct(E.score.coverage)],
    ]);
    byId("ess-caption").textContent =
      `Each 200-patient trial is analysed four ways (1000 trials). A score learned from ${h} historical patients explains R² = ${fx(E.scoreR2, 2)} of the outcome in new patients, so adjusting for that single number makes the trial worth ${n + E.score.extraPatients} patients, against ${n + E.all.extraPatients} for linear adjustment on all 10 raw covariates.`;
    byId("ess-table").innerHTML = table(
      ["Analysis", "Mean, m", "SD, m", "Cover", "Eff. n"],
      rows.map(([name, s]) => [name, m(s.mean, 2), m(s.sd, 2), pct(s.coverage), n + s.extraPatients]),
      "1000 repeated trials, truth 15 m: mean estimate, SD, coverage, effective sample size",
    );
  }

  function sliderValues() {
    const c = state.get();
    byId("r2-v").textContent = fx(nearest(G.r2, c.r2), 1);
    byId("curve-v").textContent = fx(nearest(G.curve, c.curve), 2);
    byId("gap-v").textContent = fx(nearest(G.binaryGap, c.gap), 1);
    byId("het-v").textContent = m(nearest(G.het, c.het), 0) + " m";
  }
  function render() {
    sliderValues();
    if (!D) return;
    drawRepeats();
    drawAdjust();
    drawCurve();
    drawBinary();
    drawCoverage();
    drawProcova();
  }
  guided(root, state);
  tools(root, state);
  state.subscribe(render);
  let resizeTimer = null,
    lastWidth = innerWidth;
  window.addEventListener("resize", () => {
    if (innerWidth === lastWidth) return;
    lastWidth = innerWidth;
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(render, 150);
  });
  window.addEventListener("causality:settings", () => setTimeout(render, 0));
  window.addEventListener("causality:lab-reset", (e) => {
    if (e.detail?.name === "rct-adjustment") repPlayer.set(0);
  });
  fetch("../science/rct-adjustment.json")
    .then((r) => {
      if (!r.ok) throw Error("HTTP " + r.status);
      return r.json();
    })
    .then((data) => {
      D = data;
      render();
    })
    .catch((err) => {
      root.querySelectorAll(".fig-caption").forEach(
        (c) => (c.textContent = "The precomputed repeated trials could not be loaded (" + err.message + "). Serve the course over HTTP."),
      );
    });
  window.RCTLab = { state, repPlayer };
})();
